package ru.truetv.launcher;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import android.net.Uri;import android.widget.*;import android.provider.*;import android.database.*;import java.io.*;import java.net.*;import java.lang.reflect.*;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.*;import ru.truetv.bridge.*;import ru.truetv.bridge.android.*;
/** Main=receive, Share=send; real TLS and cross-UID read grants on disposable API28/34. */
public final class PhoneReceiveCheck extends Instrumentation {
 private Context c;private ReceiveActivity screen;private Activity sender;private final ExecutorService pool=Executors.newCachedThreadPool();private int checks;private final StringBuilder log=new StringBuilder();private boolean oldAuto,oldRead,oldWrite;private Identity client,receiver;private String prefix;private Set<Uri> before=new HashSet<>();private final Set<Uri> grants=new HashSet<>();private ClipData oldClip;private android.content.ClipboardManager clipboard;
 public void onCreate(Bundle b){super.onCreate(b);start();}private void check(boolean ok,String name){checks++;log.append(ok?"PASS ":"FAIL ").append(name).append('\n');if(!ok)throw new AssertionError(name);}private void main(Runnable r){runOnMainSync(r);waitForIdleSync();}private Object f(Object o,String name)throws Exception{Class<?> type=o.getClass();while(type!=null){try{Field v=type.getDeclaredField(name);v.setAccessible(true);return v.get(o);}catch(NoSuchFieldException absent){type=type.getSuperclass();}}throw new NoSuchFieldException(name);}interface Wait{boolean ok()throws Exception;}private void until(Wait w)throws Exception{long end=SystemClock.uptimeMillis()+30000;while(!w.ok()&&SystemClock.uptimeMillis()<end)Thread.sleep(100);check(w.ok(),"await condition");}private Button button(String name)throws Exception{return (Button)f(screen,name);}private int port()throws Exception{Transfer.Receiver r=(Transfer.Receiver)f(screen,"receiver");return r==null?0:r.port();}private void shell(String cmd)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(cmd))){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}private void shot(String name)throws Exception{android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image==null){log.append("SCREENSHOT unavailable on this VM display\n");return;}try(OutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),"phone105-"+name+"-api"+Build.VERSION.SDK_INT+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 private Future<Boolean> send(int port,byte[] bytes,boolean text){return pool.submit(()->{try(Transfer.Sender s=new Transfer.Sender()){s.send(client,InetAddress.getLoopbackAddress(),port,receiver.fingerprint(),new Wire.Offer("Another phone",Arrays.asList(text?SharedText.item(bytes):new Wire.Item(prefix+".bin","application/octet-stream",bytes.length))),i->new ByteArrayInputStream(bytes),new Transfer.ClientEvents(){public void waiting(String a,String b,String x){}public void accepted(String f){}public void update(int i,String n,long a,long b){}});return true;}catch(Exception e){log.append("SEND ").append(e.getClass().getSimpleName()).append('\n');return false;}});}
 private Set<Uri> downloads()throws Exception{Set<Uri> out=new HashSet<>();if(Build.VERSION.SDK_INT>=29){try(Cursor q=c.getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{"_id","_display_name","is_pending"},null,null,null)){while(q!=null&&q.moveToNext())if(q.getInt(2)==0&&(q.getString(1).startsWith(prefix)||q.getString(1).startsWith("Text-")))out.add(ContentUris.withAppendedId(MediaStore.Downloads.EXTERNAL_CONTENT_URI,q.getLong(0)));}}else{File[] files=Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS).listFiles();if(files!=null)for(File p:files)if(p.getName().startsWith(prefix)||p.getName().startsWith("Text-"))out.add(Uri.fromFile(p));}return out;}
 private byte[] read(Uri uri)throws Exception{try(InputStream in="file".equals(uri.getScheme())?new FileInputStream(uri.getPath()):c.getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);return out.toByteArray();}}
 private String sha(byte[] bytes)throws Exception{StringBuilder out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
 public void onStart(){Bundle result=new Bundle();try{c=getTargetContext();check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("Android SDK"),"VM guard");prefix="phone105-"+System.currentTimeMillis();oldAuto=c.getSharedPreferences("totv_window",0).getBoolean("automatic",false);c.getSharedPreferences("totv_window",0).edit().putBoolean("automatic",false).commit();clipboard=(android.content.ClipboardManager)c.getSystemService(Context.CLIPBOARD_SERVICE);before=downloads();Intent launch=c.getPackageManager().getLaunchIntentForPackage(c.getPackageName());check(launch!=null&&ReceiveActivity.class.getName().equals(launch.getComponent().getClassName()),"ordinary app icon resolves directly to receive mode");screen=(ReceiveActivity)startActivitySync(launch);until(()->port()>0&&screen.hasWindowFocus());oldClip=clipboard.getPrimaryClip();if(oldClip!=null&&"vpn://sample?key=a%2Bb\r\nКод 1234 — text".contentEquals(oldClip.getItemAt(0).getText()))oldClip=null;receiver=Identity.load(new File(c.getFilesDir(),"to-tv-identity"));client=Identity.load(new File(c.getCacheDir(),"phone105-client"));shot("ready");check(f(screen,"registration")!=null,"visible receiver advertises through the shared discovery protocol");byte[] bytes=new byte[256*1024+29];new Random(105).nextBytes(bytes);int receivePort=port();Future<Boolean> denied=send(receivePort,bytes,false);until(()->f(screen,"decision")!=null);check(downloads().equals(before),"nothing saved before user confirmation");main(()->{try{button("reject").performClick();}catch(Exception e){throw new RuntimeException(e);}});check(!denied.get(20,TimeUnit.SECONDS)&&downloads().equals(before),"declining a phone transfer writes no file");Future<Boolean> first=send(receivePort,bytes,false);until(()->f(screen,"decision")!=null);main(()->{try{button("accept").performClick();}catch(Exception e){throw new RuntimeException(e);}});check(first.get(40,TimeUnit.SECONDS),"phone receives a confirmed real TLS transfer");until(()->button("open").getVisibility()==android.view.View.VISIBLE);ArrayList<?> files=(ArrayList<?>)f(screen,"received");Uri received=(Uri)f(files.get(0),"uri");check(Arrays.equals(read(received),bytes),"phone public Downloads content is exact");check("content".equals(received.getScheme()),"received file has an openable content URI on legacy and scoped storage");Bundle blocked=c.getContentResolver().call(Uri.parse("content://ru.truetv.session.source"),"read-granted",received.toString(),null);check(blocked.getString("error")!=null,"another UID cannot read before an exact URI grant");c.grantUriPermission("ru.truetv.session.tests",received,Intent.FLAG_GRANT_READ_URI_PERMISSION);grants.add(received);Bundle opened=c.getContentResolver().call(Uri.parse("content://ru.truetv.session.source"),"read-granted",received.toString(),null);check(opened.getString("sha256","").equals(sha(bytes))&&opened.getLong("size")==bytes.length,"separate provider UID reads exact bytes through the explicit grant");Bundle write=c.getContentResolver().call(Uri.parse("content://ru.truetv.session.source"),"write-granted",received.toString(),null);check(write.getString("error")!=null&&!write.getBoolean("write"),"read grant does not permit writes");main(()->{try{((CheckBox)f(screen,"automatic")).setChecked(true);}catch(Exception e){throw new RuntimeException(e);}});check(send(receivePort,bytes,false).get(40,TimeUnit.SECONDS),"second transfer works without reopening the phone receiver");until(()->button("open").getVisibility()==android.view.View.VISIBLE);Set<Uri> completed=downloads();completed.removeAll(before);check(completed.size()==2,"same-name transfers retain both completed files");
 String value="vpn://sample?key=a%2Bb\r\nКод 1234 — text";check(send(receivePort,SharedText.encode(value),true).get(30,TimeUnit.SECONDS),"phone receives text using the same To TV protocol");until(()->button("copyText").getVisibility()==android.view.View.VISIBLE);check(value.equals(f(screen,"receivedText")),"received text retains Unicode, URL escapes and CRLF");Set<Uri> beforeText=downloads();main(()->{try{button("copyText").performClick();}catch(Exception e){throw new RuntimeException(e);}});check(value.contentEquals(clipboard.getPrimaryClip().getItemAt(0).getText()),"phone copies the complete text only on explicit action");check(downloads().equals(beforeText),"receiving and copying text do not create a TXT");main(()->{try{button("saveText").performClick();}catch(Exception e){throw new RuntimeException(e);}});until(()->(Boolean)f(screen,"textSaved"));Set<Uri> txt=downloads();txt.removeAll(beforeText);check(txt.size()==1&&Arrays.equals(read(txt.iterator().next()),SharedText.encode(value)),"Save as TXT creates exact UTF-8 in public Downloads");main(screen::finish);until(()->port()==0);check(!send(receivePort,bytes,false).get(12,TimeUnit.SECONDS),"leaving the phone receive window closes its socket");check(f(screen,"registration")==null&&f(screen,"multicast")==null,"leaving stops advertisement and multicast lock");
 Intent share=new Intent(Intent.ACTION_SEND).setType("application/octet-stream").setPackage(c.getPackageName()).putExtra(Intent.EXTRA_STREAM,Uri.parse("content://ru.truetv.session.source/file"));ResolveInfo match=c.getPackageManager().resolveActivity(share,PackageManager.MATCH_DEFAULT_ONLY);check(match!=null&&match.activityInfo.name.equals(SendActivity.class.getName()),"Android Share resolves to sending rather than receive mode");sender=startActivitySync(share.setClass(c,SendActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));check(sender instanceof SendActivity&&f(sender,"discovery")!=null,"Share opens device discovery immediately");main(sender::finish);sender=null;result.putBoolean("passed",true);
 }catch(Throwable e){StringWriter out=new StringWriter();e.printStackTrace(new PrintWriter(out));log.append(out);result.putBoolean("passed",false);}finally{try{if(sender!=null)main(sender::finish);if(screen!=null)main(screen::finish);for(Uri uri:grants)c.revokeUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);Set<Uri> created=downloads();created.removeAll(before);for(Uri u:created)if("file".equals(u.getScheme()))new File(u.getPath()).delete();else c.getContentResolver().delete(u,null,null);c.getSharedPreferences("totv_window",0).edit().putBoolean("automatic",oldAuto).commit();if(clipboard!=null){if(oldClip!=null)clipboard.setPrimaryClip(oldClip);else if(Build.VERSION.SDK_INT>=28)clipboard.clearPrimaryClip();}}catch(Exception e){log.append("RESTORE ").append(e);}pool.shutdownNow();}result.putString("report",log+"Checks="+checks);finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
